    isStaleNonRunning: isStaleNonRunning,
    isFreshlyCompleted: isFreshlyCompleted,
    isOwningRun: isOwningRun,
    isOlderRun: isOlderRun,
    isLegWorkflowRun: isLegWorkflowRun,
    decideEventDedup: decideEventDedup
};

