    if (!labelName || typeof labelName !== 'string') return null;
    return ARMING_LABEL_LEGS.hasOwnProperty(labelName) ? ARMING_LABEL_LEGS[labelName] : null;
}

/**
 * The leg of the STRONGEST arming label on the issue (assigned events).
