function anchoredNumberOf(name, re) {
    var m = re.exec(name);
    while (m) {
        var after = name.charAt(m.index + m[0].length);
        if (after === '' || after < '0' || after > '9') return parseInt(m[1], 10);
        m = re.exec(name);
    }
    return null;
