            runs = parseWorkflowRuns(scm.listWorkflowRuns(statuses[i], workflowFile, 50));
        } catch (ePullLeg) {
            console.warn('  ⚠️  Could not inspect active workflow runs (' + statuses[i] + '): ' + (ePullLeg.message || ePullLeg));
